fn abs_sum(xs: List[Int]) -> Int
  requires true
  ensures result >= 0
  effects pure
  example abs_sum([]) == 0
  example abs_sum([1, -2, 3]) == 6
  example abs_sum([-5]) == 5
{
  match xs {
    [] => 0
    [h, ..t] => abs_val(h) + abs_sum(t)
  }
}

fn clamp_all(xs: List[Int], lo: Int, hi: Int) -> List[Int]
  requires lo <= hi
  ensures length(result) == length(xs)
  effects pure
  example clamp_all([], 0, 10) == []
  example clamp_all([1, 5, 12], 0, 10) == [1, 5, 10]
  example clamp_all([-5, 3, 20], 0, 10) == [0, 3, 10]
{
  match xs {
    [] => []
    [h, ..t] => [clamp(h, lo, hi)] ++ clamp_all(t, lo, hi)
  }
}

fn max_list(xs: List[Int]) -> Option[Int]
  requires true
  ensures (length(xs) == 0 and result == None) or (length(xs) > 0 and result != None)
  effects pure
  example max_list([]) == None
  example max_list([1, 5, 3]) == Some(5)
  example max_list([-3, -7, -1]) == Some(-1)
  example max_list([42]) == Some(42)
{
  match xs {
    [] => None
    [h, ..t] => Some(match max_list(t) {
      None => h
      Some(m) => max_of(h, m)
    })
  }
}

fn max_list(xs: List[Int]) -> Option[Int]
  requires true
  ensures ((length(xs) == 0) and (result == None)) or ((length(xs) > 0) and (result != None))
  effects pure
  example max_list([]) == None
  example max_list([1, 2, 3]) == Some(3)
  example max_list([5, 1, 2]) == Some(5)
  example max_list([-1, -5, -2]) == Some(-1)
{
  match xs {
    [] => None
    [h, ..t] => match max_list(t) {
      None => Some(h)
      Some(m) => Some(max_of(h, m))
    }
  }
}
